import React from 'react';
import './Share.css';



function Share(User) {
    return (
        <div className='Share'>
              <ul clas="list-group">
                     <li class="list-group-item d-flex align-items-center">
                         <span >publish now</span>
                     </li>
                     <li class="list-group-item d-flex align-items-center">
                         <span >share in feed</span>
                     </li>
                     <li class="list-group-item d-flex align-items-center">
                         <span >share to story</span>
                     </li>
                     <li class="list-group-item d-flex align-items-center">
                         <span >send in Messenger</span>
                     </li>
                     </ul>
        
 
                </div>
            );    
}
export default Share;
